function addFriend(state:GameState,id='location-scene-friend',age=30){
  const npc:Npc={id,firstName:'Riley',lastName:'Thread',age,alive:true,health:80,happiness:70,wealth:15000,countryId:state.character.countryId,city:state.character.city,sexuality:'bisexual',fertility:60,maritalStatus:'single',traits:['calm'],hiddenOpinion:10,memories:[],parentIds:[],childIds:[],simulationTier:'full'};
  const rel:Relationship={id:`rel-${id}`,npcId:id,type:'friend',score:70,attraction:40,compatibility:75,yearsKnown:4};
  state.npcs[id]=npc;state.relationships.push(rel);return{npc,rel};
}

function schoolState(seed:string,age=14){
  const state=createNewGame({seed,countryId:'everthread',city:'Everthread'});state.character.age=age;state.currentYear=2040;state.actionLedger.age=age;state.actionLedger.uses={};
  const record:GameState['education'][number]={stage:'secondary',institution:'Everthread Secondary School',startAge:14,graduated:false,droppedOut:false,scholarship:false,performance:state.character.secondary.academicPerformance};
  state.education=[record];ensureSchoolWorldForEducationRecord(state,record,false);return{state,record,world:currentSchoolWorld(state)!};
}

function collegeState(seed:string,age=20){
  const state=createNewGame({seed,countryId:'everthread',city:'Everthread'});state.character.age=age;state.currentYear=2046;state.actionLedger.age=age;state.actionLedger.uses={};
  const record:GameState['education'][number]={stage:'university',institution:'Everthread Institute of Computer Science',programId:'computer_science',major:'Computer Science',startAge:18,graduated:false,droppedOut:false,scholarship:false,performance:state.character.secondary.academicPerformance};
  state.education=[record];ensureSchoolWorldForEducationRecord(state,record,false);return{state,record,world:currentSchoolWorld(state)!};
}

